{"path": "two_bucket.py", "content": "from collections import deque


def measure(bucket_one, bucket_two, goal, start_bucket):
    if start_bucket not in ("one", "two"):
        raise ValueError("start_bucket must be 'one' or 'two'")
    caps = (bucket_one, bucket_two)
    if start_bucket == "one":
        start = (bucket_one, 0)
        forbidden = (0, bucket_two)
    else:
        start = (0, bucket_two)
        forbidden = (bucket_one, 0)

    seen = {start}
    queue = deque([(start, 1)])
    while queue:
        (a, b), moves = queue.popleft()
        if a == goal:
            return (moves, "one", b)
        if b == goal:
            return (moves, "two", a)
        pour_ab = min(a, caps[1] - b)
        pour_ba = min(b, caps[0] - a)
        for nxt in (
            (caps[0], b),
            (a, caps[1]),
            (0, b),
            (a, 0),
            (a - pour_ab, b + pour_ab),
            (a + pour_ba, b - pour_ba),
        ):
            if nxt != forbidden and nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, moves + 1))
    raise ValueError("goal cannot be reached with the given buckets")
